/**
 * Skin registry. Every skin is already registered here: to add or change a cow, edit
 * ONLY its own file in this folder (see RIG_GUIDE.md). Do not edit this file.
 */
import type { CowSkin } from '../rig/types';
import attitude from './attitude';
import blob from './blob';
import classic from './classic';
import derpy from './derpy';
import sticker from './sticker';

export const SKINS: readonly CowSkin[] = [classic, blob, sticker, derpy, attitude];

export const DEFAULT_SKIN_ID = 'classic';

export function getSkin(id?: string): CowSkin {
  return SKINS.find((s) => s.id === id) ?? classic;
}
